/*
 * solver.c
 *
 * Table-driven Thistlethwaite solver. See solver.h.
 */
#include "solver.h"

#include "coords.h"
#include "thistle_tables.h"     /* Generated by tools/gen_tables.c */

/* ------------------------------------------------------------------ */
/* Constants                                                          */
/* ------------------------------------------------------------------ */

/* Packed distance table of each phase (const, so it stays in flash). */
static const uint8_t *const PHASE_TABLES[NUM_PHASES] = {
    PHASE1_DIST, PHASE2_DIST, PHASE3_DIST, PHASE4_DIST
};

/* Number of entries in each phase's table, for bounds checking. */
static const uint32_t PHASE_STATE_COUNTS[NUM_PHASES] = {
    PHASE1_STATE_COUNT, PHASE2_STATE_COUNT, PHASE3_STATE_COUNT, PHASE4_STATE_COUNT
};

/* Returned by phase_distance() when the cube has no entry in the table. */
#define DIST_INVALID 0xFF

/* ------------------------------------------------------------------ */
/* Table lookup                                                       */
/* ------------------------------------------------------------------ */

/* Table index of `cube` for `phase`. */
static uint32_t phase_coord(const Cube *cube, uint8_t phase)
{
    switch (phase) {
    case 0:  return coord_phase1(cube);
    case 1:  return coord_phase2(cube);
    case 2:  return coord_phase3(cube, CORNER_COSET);
    default: return coord_phase4(cube, G3_CORNERS);
    }
}

/* Reads one 4-bit distance out of a packed table. */
static uint8_t table_read(const uint8_t *table, uint32_t index)
{
    /* Two entries share a byte: even indices use the low 4 bits and odd
     * indices the high 4 bits. Shift the wanted half down, then mask it. */
    uint8_t shift = (uint8_t)((index % DIST_PER_BYTE) * DIST_BITS);
    return (uint8_t)((table[index / DIST_PER_BYTE] >> shift) & DIST_MASK);
}

/* Measures the cube, then looks up how many moves it is from the phase
 * goal. This is the only place the lookup tables are read. */
uint8_t solver_phase_distance(const Cube *cube, uint8_t phase)
{
    uint32_t index = phase_coord(cube, phase);

    /* Never read outside a table (also catches COORD_INVALID). */
    if (index >= PHASE_STATE_COUNTS[phase]) {
        return DIST_INVALID;
    }
    return table_read(PHASE_TABLES[phase], index);
}

/* ------------------------------------------------------------------ */
/* Solving                                                            */
/* ------------------------------------------------------------------ */

/* Joins neighbouring turns of the same face (for example the last move of
 * one phase and the first move of the next): R R2 -> R', F2 F2 -> nothing. */
static void merge_moves(Solution *solution)
{
    uint8_t out = 0;    /* Moves kept so far; the list is rewritten in place */

    for (uint8_t in = 0; in < solution->length; in++) {
        uint8_t move = solution->moves[in];

        if (out > 0 && move_face(solution->moves[out - 1]) == move_face(move)) {
            /* Same face as the last kept move: add the quarter turns. */
            uint8_t turns = (uint8_t)((move_quarter_turns(solution->moves[out - 1]) +
                                       move_quarter_turns(move)) % QUARTER_TURNS_PER_CYCLE);
            if (turns == 0) {
                /* They cancel out. Dropping the kept move also lets the
                 * next move merge with the one before it. */
                out--;
            } else {
                solution->moves[out - 1] = move_make(move_face(move), turns);
            }
        } else {
            /* Different face: keep the move as it is. */
            solution->moves[out++] = move;
        }
    }
    solution->length = out;
}

SolveStatus solver_solve(const Cube *cube, Solution *solution)
{
    char message[MESSAGE_MAX];
    Cube work = *cube;      /* Copy that the solution is applied to as it is found */

    /* Start with an empty solution. */
    solution->length = 0;
    for (uint8_t phase = 0; phase < NUM_PHASES; phase++) {
        solution->phase_length[phase] = 0;
    }

    /* An impossible cube has no place in the tables, so refuse it now. */
    if (cube_validate(cube, message, sizeof message) != CUBE_OK) {
        return SOLVE_ERR_INVALID_CUBE;
    }

    /* Run the four phases in order. Each phase starts where the previous
     * one finished and only uses moves that keep the earlier goals intact. */
    for (uint8_t phase = 0; phase < NUM_PHASES; phase++) {
        /* How many moves is the cube from this phase's goal? */
        uint8_t distance = solver_phase_distance(&work, phase);
        if (distance == DIST_INVALID) {
            return SOLVE_ERR_TABLE;
        }

        /* Follow decreasing distances until the phase goal is reached.
         * Because the table holds exact distances, at least one allowed
         * move always leads to a state that is one move closer. */
        while (distance > 0) {
            bool stepped = false;   /* Set once a closer state has been found */

            /* Try each allowed move on a copy of the cube. */
            for (uint8_t i = 0; i < PHASE_MOVE_COUNT[phase] && !stepped; i++) {
                Cube next = work;
                cube_apply_move(&next, PHASE_MOVES[phase][i]);

                /* Keep the first move that gets one step closer. */
                if (solver_phase_distance(&next, phase) == distance - 1) {
                    if (solution->length >= MAX_SOLUTION_MOVES) {
                        return SOLVE_ERR_TABLE;
                    }
                    solution->moves[solution->length++] = PHASE_MOVES[phase][i];
                    solution->phase_length[phase]++;
                    work = next;
                    distance--;
                    stepped = true;
                }
            }
            /* No move helped: only possible if the tables are damaged. */
            if (!stepped) {
                return SOLVE_ERR_TABLE;
            }
        }
    }

    /* After phase 4 the working copy must be solved. */
    if (!cube_is_solved(&work)) {
        return SOLVE_ERR_TABLE;
    }

    /* Tidy up turns of the same face that ended up next to each other. */
    merge_moves(solution);
    return SOLVE_OK;
}
